173: fn parse_metadata_value(mmap: &[u8], mut cursor: usize, val_type: u32) -> Result<(String, usize), String> {
174:     match val_type {
175:         0 => { // UINT8
176:             let v = mmap[cursor];
177:             Ok((v.to_string(), cursor + 1))
178:         }
179:         1 => { // INT8
180:             let v = mmap[cursor] as i8;
181:             Ok((v.to_string(), cursor + 1))
182:         }
183:         2 => { // UINT16
184:             let v = LittleEndian::read_u16(&mmap[cursor..cursor + 2]);
185:             Ok((v.to_string(), cursor + 2))
186:         }
187:         3 => { // INT16
188:             let v = LittleEndian::read_i16(&mmap[cursor..cursor + 2]);
189:             Ok((v.to_string(), cursor + 2))
190:         }
191:         4 => { // UINT32
192:             let v = LittleEndian::read_u32(&mmap[cursor..cursor + 4]);
193:             Ok((v.to_string(), cursor + 4))
194:         }
195:         5 => { // INT32
196:             let v = LittleEndian::read_i32(&mmap[cursor..cursor + 4]);
197:             Ok((v.to_string(), cursor + 4))
198:         }
199:         6 => { // FLOAT32
200:             let v = LittleEndian::read_f32(&mmap[cursor..cursor + 4]);
201:             Ok((v.to_string(), cursor + 4))
202:         }
203:         7 => { // BOOL
204:             let v = mmap[cursor] != 0;
205:             Ok((v.to_string(), cursor + 1))
206:         }
207:         8 => { // STRING
208:             let s_len = LittleEndian::read_u64(&mmap[cursor..cursor + 8]) as usize;
209:             cursor += 8;
210:             let s = std::str::from_utf8(&mmap[cursor..cursor + s_len])
211:                 .map_err(|e| format!("String inválido: {}", e))?
212:                 .to_string();
213:             Ok((s, cursor + s_len))

